import string
def underscore(text):
    for c in string.punctuation:
        text = text.replace(c, "_")
    return text

def censor_boring_words(text):
    boring_words = set(text.split())
    for word in boring_words:
        text = text.replace(word, "*"*len(word))

    return text

unction_reference = censor_boring_words

text = "I am feeling so bored. This is a waste of time."
print(unction_reference(text))

import random

def suggest_boardgames(num_players):
    boardgame1 = "Settlers of Catan"
    boardgame2 = "Pandemic"
    boardgame3 = "Ticket to Ride"
    boardgame4 = "Carcassonne"
    boardgame5 = "Twilight Struggle"

    suggested_games = {
        2: boardgame4,
        3: boardgame5,
        4: boardgame3,
        5: boardgame2,
        6: boardgame1
    }

    if num_players in suggested_games.keys():
        return suggested_games[num_players]

    else:
        return random.choice([boardgame1, boardgame2, boardgame3, boardgame4, boardgame5])

print(suggest_boardgames(5))

