from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/data', methods=['POST'])
def handle_data():
    data = request.json
    success, error = validate_data(data)
    if not success:
        return error

    username = data['username']
    name = data['name']
    bio = data['bio']

    return jsonify({'username': username, 'name': name, 'bio': bio})

def validate_data(data):
    username = data['username']
    name = data['name']
    bio = data['bio']

    if not username:
        return (False, 'Username is required!')
    elif len(username) < 3:
        return (False, 'Username must be at least 3 characters long!')
    if not name:
        return (False, 'Name is required!')
    if bio and len(bio) > 200:
        return (False, 'Bio cannot exceed 200 characters!')

    return (True, '')

if __name__ == '__main__':
    app.run()

