import random

def get_vocals():
    vocals = ['a', 'e', 'i', 'o', 'u']
    return random.randint(1, 5)

def is_vocal(vocal):
    return vocal in {'a', 'e', 'i', 'o', 'u'}

def main():
    letters = []
    for _ in range(get_vocals()):
        letters.append(random.choice('abcdefghijklmnopqrstuvwxyz'))

    print("Guess if these are vocs or not!")
    for letter in letters:
        print(f"Is {letter} a vocal? {is_vocal(letter)}")

main()

from jinja2 import Template

def render_html(movies):
    rendered_html = []
    template = Template("<p>{{ name }}</p>", autoescape=False)

    for movie in movies:
      name = movie['name']
      description = movie['description'].replace(' ', '&nbsp;')
      rendered_html.append(template.render(name=name))
      rendered_html.append(f"<div>{description}</div>")

    return '<br>'.join(rendered_html)

