import requests

def get_joke():
    url = 'https://official-joke-api.appspot.com/random_joke'
    response = requests.get(url)
    if response.status_code == 200:
        joke = response.json()
        return joke['setup'] + '\n\n' + joke['punchline']
    else:
        return 'Failed to fetch a joke'

print(get_joke())

import random

def rate_essay(essay):
    score = 0
    keywords = ['education', 'struggle', 'perseverance']

    if 'success' in essay:
        score += 2

    for keyword in keywords:
        appearances = essay.count(keyword)
        score += appearances

    return score + random.randint(-1, 1)

essay = "Education and perseverance have led me to success."

print(f"Essay score: {rate_essay(essay)}")

