import asyncio

async def measure_health():
    while True:
        await asyncio.sleep(60)
        print("Checking vitals...")

async def handle_emergency(vital_reading):
    if vital_reading < 30:
        print("Calling 911! Please open door to let air in.")
    else:
        print("Vitals are stable. No immediate action required.")

