import random

def generate_maze(width, height):
    maze = [[' ' for x in range(width)] for y in range(height)]
    goal_positions = [()]
    for y in range(height):
        for x in range(width):
            if (x, y) in goal_positions:
                num = random.randint(1, 5)
                if num == 1:
                    maze[y][x] = '|'
                elif num == 2:
                    maze[y][1] = '-'
                elif num == 3:
                    maze[y][1] = '+'
                elif num == 4:
                    maze[y][1] = ['/', '\\'][random.randint(0, 1)]
            else:
                maze[y][x] = '.'
    return maze

