    urls = get_urls('repos.json')
    for url in urls:
        print(url)

import random

class WorkLog:
    def __init__(self, name):
        self.name = name
        self.actions = []

    def add_action(self, task):
        self.actions.append(task)

    def view_log(self):
        return self.name + "'s Logs:\n" + "\n".join(self.actions)


class Project:
    def __init__(self, name, budget):
        self.name = name
        self.budget = budget
        self.clients = set()
        self.work_logs = {}

    def add_client(self, client):
        if client not in self.clients:
            self.clients.add(client)
            self.work_logs[client] = WorkLog(client)

    def log_action(self, client, action):
        self.work_logs[client].add_action(action)

    def view_project(self):
        logs = "\n".join([w.view_log() for w in self.work_logs.values()])
        return f"{self.name} Logs\n{logs}"

    def make_offer(self):
        amount = random.randint(50, 200)
        return f"Project {self.name} requires {self.budget} cash. We can offer {amount}."


project = Project("Web Design", 400)
project.add_client("Alibaba")
project.add_client("Taobao")

project.log_action("Alibaba", "Received first visuals")
project.log_action("Taobao", "Approved final design")

print(project.view_project())

print(project.make_offer())

