from nltk import tokenize

def split_topic_file(text):
    paragraphs = tokenize.paragraph_tokenize(text)
    topics = []
    for p in paragraphs:
        topics.extend(p.split('.'))
    return topics

def word_count(tokens):
    return len(tokens)

def get_topic_sentences(text):
    topics = split_topic_file(text)
    num_topics = 0
    max_topics = 5

    for topic in topics:
        words = tokenize.word_tokenize(topic)
        num_topics += 1
        if num_topics == max_topics:
            return words

    return tokenize.word_tokenize(text)

text = "Alibaba has proposed a new concept in the field of cloud computing and big data management. This new idea is being developed as a part of their extended capabilities in the market. The main goal of this project is to unleash the true potential of data analytics."

sentences = get_topic_sentences(text)
print(" ".join(sentences))

