import sys

messages = []
for line in sys.stdin:
    line = line.strip()
    if line == '-messages':
        break
    messages.append(line)

for message in messages:
    if 'historic event' in message:
        sys.stdout.write(message.replace('historic event', 'moment'))
    else:
        sys.stdout.write(message)

