import random

HISTORY_PERSONS = [
    {
        'name': 'Genghis Khan',
        'description': 'Mongol conqueror, founder of the Mongol Empire'
    },
    {
        'name': 'Thomas Jefferson',
        'description': 'Third President of the US'
    },
    {
        'name': 'Qin Shi Huang',
        'description': 'First Emperor of China who unified China in 221 BC'
    },
    {
        'name': 'Jack London',
        'description': 'American novelist and journalist'
    }
]

def generate_dinner_invites(num_invites):
    invites = random.sample(HISTORY_PERSONS, num_invites)
    return invites

print(generate_dinner_invites(3))

def dinner_party_biographies(people):
    for person in people:
        print(f"Biography: {person.biography}")
        print(f"Signature dish: {person.signature_dish()}\n")

