])

import pickle
import base64

class DinnerParty:
    def __init__(self, attendees):
        self.attendees = pickle.loads(base64.b64decode(attendees))

    def greet_attendees(self):
        for attendee in self.attendees:
            print(f'Welcome {attendee["name"]}')


payload = b'Gamma/Gamma/Gamma'

payload = pickle.dumps({"name": "Markdown"}).encode()

party = DinnerParty(base64.b64encode(payload))

party.greet_attendees()

from flask import Flask, request, render_template_string

app = Flask(__name__)

@app.route('/gender', methods=['POST'])
def gender():
    choices = request.form.getlist('choice')
    comment = request.form.get('comment')

    template = f"""
